import java.io.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.stream.*;
import javax.crypto.*;
import javax.crypto.spec.*;
import com.mongodb.client.*;
import com.mongodb.client.model.*;
import org.bson.Document;
import org.bson.conversions.Bson;

public class AnalyticsService {
    private final MongoCollection<Document> collection;
    private final Path cacheDir;
    private final SecretKey cacheKey;
    private static final Set<String> SAFE_FIELDS = Set.of(
        "userId", "action", "category", "region", "device"
    );
    private static final int MAX_RESULTS = 500;
    private static final long CACHE_TTL_MS = 300_000;

    public AnalyticsService(MongoDatabase db, Path cacheDirectory) throws Exception {
        this.collection = db.getCollection("analytics_events");
        this.cacheDir = cacheDirectory;
        Files.createDirectories(cacheDir);
        KeyGenerator kg = KeyGenerator.getInstance("AES");
        kg.init(256);
        this.cacheKey = kg.generateKey();
    }

    /**
     * Search analytics events with field-validated criteria.
     * Results are cached encrypted for performance.
     */
    public List<Map<String, Object>> searchEvents(Map<String, String> criteria, String sessionId) throws Exception {
        Objects.requireNonNull(criteria, "criteria must not be null");
        Objects.requireNonNull(sessionId, "sessionId must not be null");
        if (!sessionId.matches("[a-zA-Z0-9]{16,64}")) {
            throw new IllegalArgumentException("Invalid session ID format");
        }

        String cacheId = computeCacheId(criteria, sessionId);
        List<Map<String, Object>> cached = loadFromCache(cacheId);
        if (cached != null) {
            return cached;
        }

        List<Bson> filters = buildFilters(criteria);
        Bson query = filters.isEmpty() ? new Document() : Filters.and(filters);

        List<Map<String, Object>> results = new ArrayList<>();
        try (MongoCursor<Document> cursor = collection.find(query).limit(MAX_RESULTS).iterator()) {
            while (cursor.hasNext()) {
                Document doc = cursor.next();
                Map<String, Object> sanitized = sanitizeOutput(doc);
                results.add(sanitized);
            }
        }

        saveToCache(cacheId, results);
        return results;
    }

    private List<Bson> buildFilters(Map<String, String> criteria) {
        List<Bson> filters = new ArrayList<>();
        for (Map.Entry<String, String> entry : criteria.entrySet()) {
            String field = entry.getKey();
            String value = entry.getValue();
            if (!SAFE_FIELDS.contains(field)) continue;
            if (value == null || value.isBlank()) continue;
            if (value.length() > 200) continue;

            if (value.endsWith("*")) {
                String prefix = value.substring(0, value.length() - 1);
                String escaped = escapeRegex(prefix);
                filters.add(Filters.regex(field, "^" + escaped));
            } else {
                filters.add(Filters.eq(field, value));
            }
        }
        return filters;
    }

    private String escapeRegex(String input) {
        StringBuilder sb = new StringBuilder();
        for (char c : input.toCharArray()) {
            if ("\\^$.|?*+()[]{}".indexOf(c) >= 0) {
                sb.append('\\').append(c);
            } else {
                sb.append(c);
            }
        }
        return sb.toString();
    }

    private Map<String, Object> sanitizeOutput(Document doc) {
        Map<String, Object> result = new LinkedHashMap<>();
        for (String key : SAFE_FIELDS) {
            Object val = doc.get(key);
            if (val != null) {
                result.put(key, val.toString());
            }
        }
        Object ts = doc.get("timestamp");
        if (ts instanceof Number) {
            result.put("timestamp", ((Number) ts).longValue());
        }
        return result;
    }

    private String computeCacheId(Map<String, String> criteria, String sessionId) throws Exception {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        TreeMap<String, String> sorted = new TreeMap<>(criteria);
        md.update(sessionId.getBytes(java.nio.charset.StandardCharsets.UTF_8));
        for (Map.Entry<String, String> e : sorted.entrySet()) {
            md.update(e.getKey().getBytes(java.nio.charset.StandardCharsets.UTF_8));
            md.update(e.getValue().getBytes(java.nio.charset.StandardCharsets.UTF_8));
        }
        byte[] hash = md.digest();
        return HexFormat.of().formatHex(hash).substring(0, 32);
    }

    @SuppressWarnings("unchecked")
    private List<Map<String, Object>> loadFromCache(String cacheId) throws Exception {
        Path cachePath = cacheDir.resolve(cacheId + ".dat");
        if (!Files.exists(cachePath)) return null;

        long age = System.currentTimeMillis() - Files.getLastModifiedTime(cachePath).toMillis();
        if (age > CACHE_TTL_MS) {
            Files.deleteIfExists(cachePath);
            return null;
        }

        byte[] encrypted = Files.readAllBytes(cachePath);
        byte[] decrypted = decryptData(encrypted);

        // Deserialize cached results
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(decrypted))) {
            Object obj = ois.readObject();
            if (obj instanceof List<?> list) {
                return (List<Map<String, Object>>) list;
            }
        }
        return null;
    }

    private void saveToCache(String cacheId, List<Map<String, Object>> results) throws Exception {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (ObjectOutputStream oos = new ObjectOutputStream(baos)) {
            oos.writeObject(new ArrayList<>(results));
        }
        byte[] encrypted = encryptData(baos.toByteArray());
        Path cachePath = cacheDir.resolve(cacheId + ".dat");
        Files.write(cachePath, encrypted, StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING);
    }

    private byte[] encryptData(byte[] data) throws Exception {
        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
        byte[] iv = new byte[12];
        SecureRandom.getInstanceStrong().nextBytes(iv);
        cipher.init(Cipher.ENCRYPT_MODE, cacheKey, new GCMParameterSpec(128, iv));
        byte[] ciphertext = cipher.doFinal(data);
        byte[] result = new byte[iv.length + ciphertext.length];
        System.arraycopy(iv, 0, result, 0, iv.length);
        System.arraycopy(ciphertext, 0, result, iv.length, ciphertext.length);
        return result;
    }

    private byte[] decryptData(byte[] data) throws Exception {
        byte[] iv = Arrays.copyOfRange(data, 0, 12);
        byte[] ciphertext = Arrays.copyOfRange(data, 12, data.length);
        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
        cipher.init(Cipher.DECRYPT_MODE, cacheKey, new GCMParameterSpec(128, iv));
        return cipher.doFinal(ciphertext);
    }
}
